import { z } from 'zod';

/**
 * Every id is a ULID with a type prefix, e.g. `tsk_01J9Z3…`. The prefix makes ids
 * self-describing in logs and lets the human app's <Ref> component open the right drawer.
 * Ids are generated by the hub's IdGen and passed into core through ctx (never inside core).
 */
export const ID_PREFIX = {
  project: 'prj',
  agent: 'agt',
  human: 'hum',
  task: 'tsk',
  entry: 'ent',
  ticket: 'tkt',
  message: 'msg',
  request: 'req',
  changeRequest: 'chg',
  vote: 'vot',
  timer: 'tmr',
  pairing: 'pair',
  subscription: 'sub',
  lock: 'lck',
  repo: 'rep',
} as const;

export type IdKind = keyof typeof ID_PREFIX;

const ULID = '[0-9A-HJKMNP-TV-Z]{26}';

export function idSchema<K extends IdKind>(kind: K) {
  return z.string().regex(new RegExp(`^${ID_PREFIX[kind]}_${ULID}$`)).brand<K>();
}

export const ProjectId = idSchema('project');
export type ProjectId = z.infer<typeof ProjectId>;
export const AgentId = idSchema('agent');
export type AgentId = z.infer<typeof AgentId>;
export const TaskId = idSchema('task');
export type TaskId = z.infer<typeof TaskId>;
export const EntryId = idSchema('entry');
export type EntryId = z.infer<typeof EntryId>;
export const TicketId = idSchema('ticket');
export type TicketId = z.infer<typeof TicketId>;
export const MessageId = idSchema('message');
export type MessageId = z.infer<typeof MessageId>;
export const RequestId = idSchema('request');
export type RequestId = z.infer<typeof RequestId>;
export const ChangeRequestId = idSchema('changeRequest');
export type ChangeRequestId = z.infer<typeof ChangeRequestId>;
export const VoteId = idSchema('vote');
export type VoteId = z.infer<typeof VoteId>;
export const PairingId = idSchema('pairing');
export type PairingId = z.infer<typeof PairingId>;
export const RepoId = idSchema('repo');
export type RepoId = z.infer<typeof RepoId>;

/** A git object id (sha-1 or sha-256). */
export const Sha = z.string().regex(/^[0-9a-f]{40}([0-9a-f]{24})?$/).brand<'sha'>();
export type Sha = z.infer<typeof Sha>;
